package com.greenocean.backend.catalog.service;
import com.greenocean.backend.wellbeing.service.PrivateWellbeing;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
/** Bounded immutable educational structure; no private learner response is part of a curriculum. */
public final class Curriculum {
 private Curriculum(){}
 private static String text(Object value,int max,boolean required){if(value!=null&&!(value instanceof String))throw new IllegalArgumentException("Expected educational text");return PrivateWellbeing.text((String)value,max,required);}
 private static Map<String,Object> object(Object raw,Set<String> allowed){if(!(raw instanceof Map<?,?> map)||!allowed.containsAll(map.keySet()))throw new IllegalArgumentException("Invalid curriculum fields");return new LinkedHashMap<>((Map<String,Object>)map);}
 private static List<?> list(Object raw,int maximum){if(!(raw instanceof List<?> list)||list.size()>maximum)throw new IllegalArgumentException("Curriculum list is missing or too large");return list;}
 public static List<Map<String,Object>> validate(Object raw,boolean submitted){var modules=new ArrayList<Map<String,Object>>();if(raw==null){if(submitted)throw new IllegalArgumentException("A real curriculum is required");return modules;}int count=0,required=0;for(Object m:list(raw,12)){var module=object(m,Set.of("title","lessons"));module.put("title",text(module.get("title"),200,submitted));var lessons=new ArrayList<Map<String,Object>>();for(Object l:list(module.get("lessons"),50)){if(++count>50)throw new IllegalArgumentException("At most fifty actual lessons");var lesson=object(l,Set.of("key","title","body","objectives","minutes","required","exercise"));lesson.put("title",text(lesson.get("title"),300,submitted));lesson.put("body",text(lesson.get("body"),20000,submitted));lesson.put("objectives",text(lesson.get("objectives"),2000,submitted));if(submitted&&((String)lesson.get("body")).length()<80)throw new IllegalArgumentException("A lesson needs genuine educational text, not a placeholder");Object minutes=lesson.getOrDefault("minutes",5);if(!(minutes instanceof Number n)||n.intValue()<1||n.intValue()>120)throw new IllegalArgumentException("Lesson estimate must be one to 120 minutes");lesson.put("minutes",((Number)minutes).intValue());Object needed=lesson.getOrDefault("required",true);if(!(needed instanceof Boolean))throw new IllegalArgumentException("Required lesson flag must be boolean");lesson.put("required",needed);if(Boolean.TRUE.equals(needed))required++;if(lesson.get("key")!=null)lesson.put("key",UUID.fromString(text(lesson.get("key"),36,true)).toString());if(lesson.get("exercise")!=null){var e=object(lesson.get("exercise"),Set.of("type","instruction","choices","correctIndex","explanation"));String type=text(e.get("type"),20,true);if(!Set.of("REFLECTION","CHECKLIST","CHOICE").contains(type))throw new IllegalArgumentException("Unsupported learning activity");e.put("instruction",text(e.get("instruction"),4000,submitted));if(type.equals("CHOICE")){var options=list(e.get("choices"),6).stream().map(v->text(v,1000,submitted)).toList();if(options.size()<2||!(e.get("correctIndex") instanceof Number index)||index.intValue()<0||index.intValue()>=options.size())throw new IllegalArgumentException("A factual learning check needs choices and a valid reference answer");e.put("choices",options);e.put("correctIndex",((Number)e.get("correctIndex")).intValue());e.put("explanation",text(e.get("explanation"),4000,submitted));}else{e.remove("choices");e.remove("correctIndex");e.remove("explanation");}lesson.put("exercise",e);}lessons.add(lesson);}if(submitted&&lessons.isEmpty())throw new IllegalArgumentException("Each module needs actual lessons");module.put("lessons",lessons);modules.add(module);}if(submitted&&(count==0||required==0))throw new IllegalArgumentException("A course requires actual required lessons");return modules;}
 public static List<Map<String,Object>> identify(JdbcTemplate db,UUID course,Object raw){var modules=validate(raw,false);var keys=new HashSet<UUID>();for(var module:modules)for(var lesson:(List<Map<String,Object>>)module.get("lessons")){UUID key;if(lesson.get("key")==null){key=db.queryForObject("INSERT INTO learning_lesson_identities(course_id) VALUES (?) RETURNING lesson_key",UUID.class,course);lesson.put("key",key.toString());}else{key=UUID.fromString((String)lesson.get("key"));if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_lesson_identities WHERE lesson_key=? AND course_id=?)",Boolean.class,key,course)))throw new IllegalArgumentException("Lesson identity belongs to another curriculum; new lessons receive server identities");}if(!keys.add(key))throw new IllegalArgumentException("A lesson may appear only once in a curriculum");}return modules;}
}
